<script>
document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('vehicleEditForm');if(!form)return;const division=form.querySelector('[name="division_id"]'),location=form.querySelector('[name="location_id"]'),save=form.querySelector('[type="submit"]');if(!division||!location||!save)return;const original={division:division.value,location:location.value};const names={division:Object.fromEntries([...division.options].map(o=>[o.value,o.text])),location:Object.fromEntries([...location.options].map(o=>[o.value,o.text]))};const panel=document.createElement('section');panel.className='vehicle-transfer-panel';panel.hidden=true;panel.innerHTML='<header class="vehicle-transfer-header"><i class="bi bi-arrow-left-right"></i><div><h2>Transferência de veículo</h2><p>Os registros históricos permanecerão vinculados à localidade em que foram realizados.</p></div></header><div class="vehicle-transfer-summary"><div><span>Origem</span><strong></strong></div><div><span>Destino</span><strong></strong></div></div><label for="transferReason">Motivo da transferência</label><textarea id="transferReason" name="transfer_reason" rows="4" placeholder="Informe o motivo da transferência do veículo."></textarea><small id="transferWordCount">0 / 5 palavras</small><label class="vehicle-transfer-confirm"><input id="transferConfirmed" type="checkbox" name="transfer_confirmed" value="1"> <span>Estou ciente da transferência deste veículo para outra localidade.</span></label>';form.insertBefore(panel,form.querySelector('.vehicle-edit-actions'));const reason=panel.querySelector('#transferReason'),confirmed=panel.querySelector('#transferConfirmed'),count=panel.querySelector('#transferWordCount');const changed=()=>division.value!==original.division||location.value!==original.location;const words=()=>((reason.value.match(/[\p{L}\p{N}]+/gu)||[]).length);const sync=()=>{const active=changed();panel.hidden=!active;if(!active){reason.value='';confirmed.checked=false;save.disabled=false;save.innerHTML='<i class="bi bi-floppy"></i> Salvar alterações';return}panel.querySelectorAll('strong')[0].textContent=`${names.division[original.division]} / ${names.location[original.location]}`;panel.querySelectorAll('strong')[1].textContent=`${names.division[division.value]} / ${names.location[location.value]}`;count.textContent=`${words()} / 5 palavras`;save.disabled=words()<5||!confirmed.checked;save.innerHTML='<i class="bi bi-arrow-left-right"></i> Confirmar transferência';};[division,location,reason,confirmed].forEach(e=>e.addEventListener(e===confirmed?'change':'input',sync));division.addEventListener('change',sync);location.addEventListener('change',sync);sync()});
</script>
